mapper.select:
select space_id, scope_type, scope_id, context_state_json
from wiki_chat_session
where session_id = #{sessionId} and created_by = #{username}

mapper.update:
update wiki_chat_session
set context_state_json = #{contextState}, update_time = now()
where session_id = #{sessionId} and created_by = #{username}

mapper.select:
select session_id sessionId, space_id spaceId, scope_type scopeType,
       scope_id scopeId, title, update_time updatedAt
from wiki_chat_session
where created_by = #{username}
order by update_time desc
limit #{limit}

select role, content from wiki_chat_message
where session_id = #{sessionId} and created_by = #{username}
order by message_id desc
limit #{limit}

select message_id, role, content, create_time
from wiki_chat_message
where session_id = #{sessionId} and created_by = #{username}
order by message_id desc
limit #{limit}
